const crypto = require('crypto');
const validate   = $('Validate Revision Request1').first().json;
const ccoResult  = $('HTTP: CCO Revised QC1').first().json;
const checkCount = $('Check Revision Count1').first().json;

// Check Visual Score1 only runs when the visual QC branch executes.
// Safely read it — if the node didn't run, treat as no visual data.
let visualCheck = null;
try { visualCheck = $('Check Visual Score1').first().json; } catch(_) {}

const visualQcResults = (visualCheck && visualCheck.visual_score !== null && visualCheck.visual_score !== undefined) ? [{
  post_id:       validate.post_id,
  visual_score:  visualCheck.visual_score,
  visual_issues: visualCheck.visual_issues || [],
  violations:    visualCheck.violations    || [],
}] : [];

const bodyObj = {
  flow_id:  'N8N-B03',
  brand_id: validate.brand_id,
  payload: {
    request_type:    'revision',
    trigger_payload: {},
    cco_results: ccoResult.result || [],
    visual_qc_results:       visualQcResults,
    evidence_bundle_states:  checkCount.evidence_bundle_states || {},
    occasion_flags:          checkCount.occasion_flags || [],
  }
};
const bodyStr = JSON.stringify(bodyObj);
const secret = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
