// Builds the /api/image/generate payload for B03 image regeneration.
// Hard Rule #3: NO Arabic in prompt_en.
const ARABIC_RE = /[؀-ۿ]/;

const validate     = $('Validate Revision Request1').first().json;
const revisedCaption = $('HTTP: DeepSeek Revised Caption1').first().json.result.posts[0];
const brandData    = $('Supabase: Fetch Brand Profile1').first().json;
const originalPost = $('Check Revision Count1').first().json;

// on_demand_requests row — may be absent for A01 monthly-batch posts.
let onDemandReq = null;
try {
  const items = $('Supabase: Fetch OnDemand Request1').all();
  if (items.length > 0 && items[0].json && items[0].json.request_id) {
    onDemandReq = items[0].json;
  }
} catch (e) { onDemandReq = null; }

// CEO-selected chain_id (if available from scope revision).
let chainId = null;
try {
  const ceoResult = $('HTTP: CEO Scope Revision1').first().json;
  chainId = ceoResult?.result?.decision?.selected_chain || null;
} catch (e) { chainId = null; }

// Prompt source priority:
//   1. admin prompt_override.hero_concept
//   2. on_demand_requests.hero_concept + style_descriptor
//   3. DeepSeek revised visual_brief_en
//   4. Generic brand fallback
let promptEn = '';

const override = validate.prompt_override || null;
if (override && override.special_instructions && !ARABIC_RE.test(override.special_instructions)) {
  promptEn = override.special_instructions.trim();
}
if (!promptEn && override && override.hero_concept) {
  const parts = [override.hero_concept];
  if (override.style_descriptor) parts.push(override.style_descriptor);
  const ov = parts.join('. ').trim();
  if (ov && !ARABIC_RE.test(ov)) promptEn = ov;
}
if (!promptEn && onDemandReq && onDemandReq.hero_concept) {
  const parts = [onDemandReq.hero_concept];
  if (onDemandReq.style_descriptor) parts.push(onDemandReq.style_descriptor);
  promptEn = parts.join('. ').trim();
}
if (!promptEn) {
  promptEn = (revisedCaption.visual_brief_en || '').trim();
}
if (!promptEn || ARABIC_RE.test(promptEn)) {
  promptEn = `${brandData.brand_name_en || 'brand'} product photo, clean background, natural lighting`;
}

const primaryColorHex = (onDemandReq && Array.isArray(onDemandReq.color_palette) && onDemandReq.color_palette.length > 0)
  ? onDemandReq.color_palette[0]
  : (brandData.primary_color_hex || '#000000');

const validObjectives = ['awareness', 'engagement', 'conversion', 'cultural', 'trust'];
const objective = (onDemandReq && validObjectives.includes(onDemandReq.objective))
  ? onDemandReq.objective
  : (revisedCaption.content_type === 'offer' ? 'conversion' : 'awareness');

const validChannels = ['Instagram', 'Snapchat', 'TikTok', 'Twitter'];
const channel = (onDemandReq && validChannels.includes(onDemandReq.platform))
  ? onDemandReq.platform
  : (brandData.primary_channel || 'Instagram');

const validDialects = ['Najdi', 'Hejazi', 'Gulf', 'MSA_formal', 'MSA_accessible', 'Mixed'];
const dialect = validDialects.includes(brandData.arabic_dialect) ? brandData.arabic_dialect : 'MSA_accessible';

// month — derive from posting_time or use current month as fallback.
let month = '';
try {
  month = (originalPost.posting_time || '').slice(0, 7);
} catch(e) {}
if (!month || !/^\d{4}-\d{2}$/.test(month)) {
  const now = new Date();
  month = now.toISOString().slice(0, 7);
}

return {
  brand_id:         validate.brand_id,
  post_id:          originalPost.post_id,
  prompt_en:        promptEn,
  brand_name_ar:    brandData.brand_name_ar || '',
  headline_ar:      (revisedCaption.caption_ar || '').slice(0, 50),
  dialect:          dialect,
  channel:          channel,
  objective:        objective,
  confidence_flag:  'clean',
  first_ever_post:  false,
  cost_constraint:  'standard',
  palette_hex:      primaryColorHex ? [primaryColorHex] : [],
  month:            month,
  score:            originalPost.cco_score ?? null,
  revision_count:   originalPost.new_revision_number || 1,
  chain_id:         chainId,
  image_model:      validate.image_model || 'auto',
  expected_media_type: (originalPost.media_type === 'video' || originalPost.format_tier === 'video') ? 'video' : 'image',
};

const visualResult = $('HTTP: Image Generate1').first().json;
const revisedCaption = $('HTTP: DeepSeek Revised Caption1').first().json.result.posts[0];
const visualCheck    = $('Check Visual Score1').first().json;
const gateResult     = $('HTTP: CEO Revision Gate1').first().json;
const gateDecision   = gateResult.result?.decision;
const originalPost   = $('Check Revision Count1').first().json;
const revision       = $('Validate Revision Request1').first().json;

// Use composite confidence score from the gate's post_scores array — this is
// the full 4-pillar score (Visual 35% + Caption 30% + Brand 20% + Occasion 15%).
// Falls back to cco_score only if gate didn't return post_scores (degraded mode).
const ccoEval = $('HTTP: CCO Revised QC1').first().json.result?.[0];
const postScore = Array.isArray(gateResult.result?.post_scores)
  ? gateResult.result.post_scores.find(p => p.post_id === revision.post_id) || gateResult.result.post_scores[0]
  : null;

// CEO gate returns scores as integer basis-points (×100) — divide to get 0-100.
const rawScore = postScore?.confidence_score ?? ccoEval?.score ?? 7500;
const confidenceScore = rawScore > 100 ? rawScore / 100 : rawScore;
const routeDecision   = postScore?.route ?? (gateDecision?.confidence_mode !== 'Standard' ? 'watermark' : 'clean');
const watermarkRequired = routeDecision === 'watermark' || routeDecision === 'hold';

const newStorageUrl =
  visualResult.result?.storage_url ||
  visualResult.storage_url || '';
if (!newStorageUrl) {
  throw new Error('Visual generation returned empty storage_url — aborting post update');
}
const newCleanStorageUrl =
  visualResult.result?.clean_storage_url ||
  visualResult.clean_storage_url || null;
const oldStorageUrl      = originalPost.storage_url || null;
const oldCleanStorageUrl = originalPost.clean_storage_url || null;
const finalCleanStorageUrl = newCleanStorageUrl || oldCleanStorageUrl;

let existingHistory = [];
const raw = originalPost.revision_history;
if (Array.isArray(raw)) {
  existingHistory = raw;
} else if (typeof raw === 'string' && raw.length > 0) {
  try { const p = JSON.parse(raw); if (Array.isArray(p)) existingHistory = p; } catch {}
}

return {
  brand_id:          revision.brand_id,
  post_id:           originalPost.post_id,
  caption_ar:        revisedCaption.caption_ar,
  storage_url:       newStorageUrl,
  clean_storage_url: finalCleanStorageUrl,
  content_type:      revisedCaption.content_type || originalPost.content_type,
  hashtags:          revisedCaption.hashtags || originalPost.hashtags || [],
  confidence_score:  confidenceScore,
  watermark:         watermarkRequired,
  route_decision:    routeDecision,
  // Client regen: set pending so the client still approves it from their calendar.
  // Admin path never reaches this node (goes to admin_regenerations insert instead).
  status:            'pending',
  visual_score:      visualCheck?.visual_score ?? null,
  visual_issues:     visualCheck?.visual_issues ?? [],
  image_prompt_en:   visualResult.result?.image_prompt_en || visualResult.image_prompt_en || null,
  revision_count:    originalPost.new_revision_number,
  revision_history: [
    ...existingHistory,
    {
      revision_number:    originalPost.new_revision_number,
      reason:             revision.revision_reason,
      old_caption:        originalPost.caption_ar,
      new_caption:        revisedCaption.caption_ar,
      old_image_url:      oldStorageUrl,
      old_clean_image_url:oldCleanStorageUrl,
      new_image_url:      newStorageUrl,
      new_clean_image_url:newCleanStorageUrl,
      confidence_score:   confidenceScore,
      visual_score:       visualCheck?.visual_score ?? null,
      route:              routeDecision,
      revised_at:         new Date().toISOString()
    }
  ],
  updated_at: new Date().toISOString()
};

const revision = $('Validate Revision Request1').first().json;
const ceoResponse = $input.first().json;
return {
  brand_id: revision.brand_id,
  post_id: revision.post_id,
  rejection_reason: ceoResponse.result?.decision?.human_gate_reasons?.join(', ') || 'CEO human gate required — manual review needed',
  flow_id: 'N8N-B03',
  status: 'rejected',
  created_at: new Date().toISOString()
};

const revisedCaption = $('HTTP: DeepSeek Revised Caption1').first().json.result.posts[0];
const gateResult     = $('HTTP: CEO Revision Gate1').first().json;
const gateDecision   = gateResult.result?.decision;
const revision       = $('Validate Revision Request1').first().json;
const visualCheck    = $('Check Visual Score1').first().json;
const ccoEval        = $('HTTP: CCO Revised QC1').first().json.result?.[0];
const visualResult   = $('Sign: Visual QC1').first().json;

// Use the real composite score (same logic as Prepare Post Update).
const postScore = Array.isArray(gateResult.result?.post_scores)
  ? gateResult.result.post_scores.find(p => p.post_id === revision.post_id) || gateResult.result.post_scores[0]
  : null;
const confidenceScore = postScore?.confidence_score ?? ccoEval?.score ?? 50;

const holdReason = 'Human override triggered: ' + ((gateDecision?.human_gate_reasons || []).join(', ') || 'confidence gate triggered');

return [{
  json: {
    brand_id:       revision.brand_id,
    post_id:        revision.post_id,
    caption_ar:     revisedCaption.caption_ar,
    storage_url:    visualResult.newStorageUrl || null,
    cco_score:      ccoEval?.score ?? null,
    confidence_score: confidenceScore,
    visual_score:   visualCheck?.visual_score ?? null,
    visual_issues:  visualCheck?.visual_issues ?? [],
    flags: {
      flow_id:     'N8N-B03',
      route:       'HOLD',
      negpat_flag: ccoEval?.negpat_flag || 'NONE',
      cultural_flag: ccoEval?.cultural_flag || false,
      issues:      ccoEval?.issues || [],
      pillars:     postScore?.pillars ?? null,
    },
    trigger_reason: holdReason,
    status:         'pending'
  }
}];

const crypto = require('crypto');
const SECRET = 'test-webhook-123';
const e = $json;

let brand_id = null;
try { brand_id = $('Validate Revision Request1').first().json.brand_id ?? null; } catch (_) {}

const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const body = JSON.stringify({
  anomaly_id:   makeUUID(),
  anomaly_type: 'revision_request_failed',
  severity:     'error',
  source_flow:  'N8N-B03',
  brand_id,
  message:      e.execution?.error?.message || 'B03 revision request flow failed',
  details: {
    failed_node:  e.execution?.lastNodeExecuted ?? null,
    error_name:   e.execution?.error?.name      ?? null,
    execution_id: e.execution?.id               ?? null,
  },
  timestamp: new Date().toISOString(),
});

const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return {
  _body: body,
  _headers: {
    'content-type':     'application/json',
    'x-n8n-signature':  sig,
    'x-n8n-request-id': `${$execution.id}-err-b03`,
    'x-n8n-timestamp':  new Date().toISOString(),
  },
};

const update = $('Prepare Post Update1').first().json;
const validate = $('Validate Revision Request1').first().json;
const post = $('Check Revision Count1').first().json;

// Next admin draft version for this post (independent of user revision_count).
let maxVersion = 0;
try {
  for (const it of $('Supabase: Fetch Admin Regen Count1').all()) {
    const v = it.json && it.json.version ? Number(it.json.version) : 0;
    if (v > maxVersion) maxVersion = v;
  }
} catch (e) { maxVersion = 0; }

return {
  post_id: update.post_id,
  request_id: validate.request_id,
  brand_id: validate.brand_id,
  version: maxVersion + 1,
  media_type: post.media_type || 'image',
  storage_url: update.storage_url,
  clean_storage_url: update.clean_storage_url,
  caption_ar: update.caption_ar,
  hashtags: update.hashtags || [],
  confidence_score: update.confidence_score,
  watermark: update.watermark,
  prompt_override: validate.prompt_override ? JSON.stringify(validate.prompt_override) : null,
  image_model: validate.image_model || 'auto',
  status: 'draft',
  visual_score: $('Check Visual Score1').first().json?.visual_score ?? null,
  visual_issues: $('Check Visual Score1').first().json?.visual_issues ?? [],
  created_by: validate.created_by
};

const crypto = require('crypto');
const validate = $('Validate Revision Request1').first().json;
const checkCount = $('Check Revision Count1').first().json;
const brandProfile = $('Supabase: Fetch Brand Profile1').first().json;
const visualResult = $input.first().json;

const newUrl =
  visualResult.result?.storage_url ||
  visualResult.storage_url || '';

// visual_brief_en = the actual English prompt that fal.ai rendered.
// V01 sub-workflow returns image_prompt_en (stored on calendar_posts).
// Using this gives GPT-4o the ground truth to score chain fidelity against,
// instead of guessing from a chain description. Matches A01/V01 path exactly.
const visualBriefEn =
  visualResult.result?.image_prompt_en ||
  visualResult.image_prompt_en ||
  checkCount.image_prompt_en ||
  null;

const bodyObj = {
  flow_id: 'N8N-B03',
  brand_id: validate.brand_id,
  payload: {
    image_url: newUrl,
    post_id: validate.post_id,
    visual_brief_en: visualBriefEn,
    chain_id: checkCount.chain_id || null,
    style_register: brandProfile.style_register || undefined,
    color_palette: (Array.isArray(brandProfile.color_palette) && brandProfile.color_palette.length > 0) ? brandProfile.color_palette : (brandProfile.primary_color_hex ? [brandProfile.primary_color_hex] : undefined),
    occasion_flags: checkCount.occasion_flags || [],
    content_type: checkCount.content_type || null,
    channel: checkCount.channel || undefined,
    religious_sensitivity: brandProfile.religious_sensitivity || 'Medium'
  }
};
const bodyStr = JSON.stringify(bodyObj);
const secret = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const ts = new Date().toISOString();
const rid = crypto.randomUUID();
const sig = crypto.createHmac('sha256', secret).update(bodyStr).digest('hex');
return { signedBody: bodyStr, sig, rid, ts, newStorageUrl: newUrl };

// Visual QC results from GPT-4o vision.
// Hard block = visual_score 0 → Saudi cultural violation. Mandatory hold on ALL paths.
// Low score  = visual_score < 50 → below doc §9.6 HOLD threshold → admin review on user path.
// Admin path ALWAYS proceeds to draft lane — admin decides after seeing the score.
const qcResult = $input.first().json;
const target = $('Validate Revision Request1').first().json.target;
const isAdminPath = target === 'admin';
const qcData = qcResult?.result ?? qcResult;
const visualScore = qcData?.visual_score ?? null;
const visualIssues = qcData?.visual_issues ?? [];
const violations   = qcData?.violations ?? [];

const isHardBlock  = visualScore === 0 || violations.length > 0;

// Doc §9.6: score < 50 = HOLD threshold (same as confidence-gate THRESHOLD_WATERMARK).
const isBelowThreshold = visualScore !== null && visualScore < 50;

// Admin drafts always proceed regardless of score — admin reviews visually.
// User path: hold on hard block or below-threshold visual.
const needsAdminReview = !isAdminPath && (isHardBlock || isBelowThreshold);

return {
  visual_score: visualScore,
  visual_issues: visualIssues,
  violations: violations,
  is_hard_block: isHardBlock,
  needs_admin_review: needsAdminReview,
  review_reason: isHardBlock
    ? `Saudi cultural hard block in regenerated image (score=0, violations: ${violations.join(', ') || 'detected'}).`
    : isBelowThreshold && !isAdminPath
    ? `Regenerated image scored ${visualScore}/100 — below the 50-point quality threshold. Admin review required before publishing.`
    : null,
};

const validate = $('Validate Revision Request1').first().json;
const visualCheck = $('Check Visual Score1').first().json;
const visualResult = $('Sign: Visual QC1').first().json;
const revisedCaption = $('HTTP: DeepSeek Revised Caption1').first().json.result.posts[0];
return [{
  json: {
    brand_id: validate.brand_id,
    post_id: validate.post_id,
    caption_ar: revisedCaption?.caption_ar ?? '',
    storage_url: visualResult.newStorageUrl,
    cco_score: visualCheck.visual_score ?? 0,
    flags: {
      flow_id: 'N8N-B03',
      route: 'HOLD',
